package org.sleepwell.app;
import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
/** Global edits use a reviewed matching-record snapshot and one transaction; raw evidence stays unchanged. */
final class TagRecords {
 static String signature(List<RecordEntry> records,String tag){List<String> rows=new ArrayList<>();for(RecordEntry row:records)if(row.edit.tags.stream().anyMatch(t->t.equalsIgnoreCase(tag)))rows.add(Records.display(row).toString()+"/"+row.rawStart+"/"+row.rawEnd+"/"+row.updated+"/"+row.source+"/"+row.origin+"/"+row.sensor+"/"+row.sensorConfig+"/"+row.soundAnalysis+"/"+row.healthConnect+"/"+TagCodec.encode(row.edit));Collections.sort(rows);return HealthSleepStore.hash(String.join("\n",rows));}
 static int change(Store store,String tag,String rename,String expected,long now){String source=RecordDraft.tag(tag),target=rename==null?null:RecordDraft.tag(rename);SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{List<RecordEntry> records=Records.all(store);if(!signature(records,source).equals(expected))throw new IllegalStateException("Tagged records changed. Review the current records and try again.");if(target!=null&&!target.equalsIgnoreCase(source)&&TagImpact.names(records).stream().anyMatch(t->t.equalsIgnoreCase(target)))throw new IllegalArgumentException("That tag already exists. Choose another name to preserve every quantity.");int changed=0;for(RecordEntry row:records){String old=row.edit.tags.stream().filter(t->t.equalsIgnoreCase(source)).findFirst().orElse(null);if(old==null)continue;RecordDraft draft=row.edit.copy();int position=draft.tags.indexOf(old);TagQuantity quantity=draft.quantities.get(old);draft.removeTag(old);if(target!=null){draft.tags.add(position,target);if(quantity!=null)draft.quantities.put(target,quantity);}Records.save(store,row.id,draft,row.updated,now);changed++;}if(changed==0)throw new IllegalStateException("This tag is no longer used.");db.setTransactionSuccessful();return changed;}finally{db.endTransaction();}}
 private TagRecords(){}
}
